# Let's search inside hid=72 or all hids for 'Food Additive' or 'NCATS'
import urllib.request, json

def search_nodes(node, query):
    hits = []
    name = node.get('Information', {}).get('Name', {}).get('StringWithMarkup', {}).get('String', '')
    if query.lower() in name.lower():
        hits.append((node.get('NodeID'), node.get('HNID'), name))
    for child in node.get('Node', []):
        hits.extend(search_nodes(child, query))
    return hits

url = 'https://pubchem.ncbi.nlm.nih.gov/classification_2/classification_2.fcgi?hid=72&format=json'
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
data = json.loads(urllib.request.urlopen(req).read().decode('utf-8'))
for h in data['Hierarchies']['Hierarchy']:
    for node in h.get('Node', []):
        res = search_nodes(node, 'Food Additive')
        if res:
            print('Found in 72:', res)
        res2 = search_nodes(node, 'NCATS')
        if res2:
            print('Found NCATS in 72:', res2)
