# Let's search all nodes across all hierarchies for NCATS
import urllib.request, json

url = 'https://pubchem.ncbi.nlm.nih.gov/classification_2/classification_2.fcgi?format=json'
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
data = json.loads(urllib.request.urlopen(req).read().decode('utf-8'))
for h in data['Hierarchies']['Hierarchy']:
    hid = h['HID']
    url_hid = f'https://pubchem.ncbi.nlm.nih.gov/classification_2/classification_2.fcgi?hid={hid}&format=json'
    try:
        req_h = urllib.request.Request(url_hid, headers={'User-Agent': 'Mozilla/5.0'})
        d = json.loads(urllib.request.urlopen(req_h).read().decode('utf-8'))

        def find_kw(node):
            name = node.get('Information', {}).get('Name', {}).get('StringWithMarkup', {}).get('String', '')
            if 'ncats' in name.lower() or 'food additive status' in name.lower():
                print(f'HID {hid} | node {node.get(\"NodeID\")} | hnid={node.get(\"HNID\")} | {name}')
            for child in node.get('Node', []):
                find_kw(child)

        for hier in d.get('Hierarchies', {}).get('Hierarchy', []):
            for node in hier.get('Node', []):
                find_kw(node)
    except Exception as e:
        pass
